function resolveLang(cfgLang) {
    if (cfgLang === 'zh' || cfgLang === 'zh-TW' || cfgLang === 'de' || cfgLang === 'fr' ||
        cfgLang === 'es' || cfgLang === 'it' || cfgLang === 'pt' || cfgLang === 'ja' || cfgLang === 'ko') {
        return cfgLang;
    }
    if (cfgLang === 'en')
        return 'en';
    return detectLang();
}
